function queryConversions(conversions, queries) {
  const MOD = 1000000007n;
  const power = (base, exponent) => {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent & 1n) result = (result * base) % MOD;
      base = (base * base) % MOD;
      exponent >>= 1n;
    }
    return result;
  };

  const n = conversions.length + 1;
  const children = Array.from({ length: n }, () => []);
  for (const [source, target, factor] of conversions) {
    children[source].push([target, BigInt(factor)]);
  }
  const amount = new Array(n).fill(0n);
  amount[0] = 1n;
  const queue = [0];
  for (let head = 0; head < queue.length; head++) {
    const unit = queue[head];
    for (const [next, factor] of children[unit]) {
      amount[next] = (amount[unit] * factor) % MOD;
      queue.push(next);
    }
  }

  const answer = [];
  for (const [unitA, unitB] of queries) {
    const inverseA = power(amount[unitA], MOD - 2n);
    answer.push(Number((amount[unitB] * inverseA) % MOD));
  }
  return answer;
}

