function queryConversions(conversions, queries) {
  const MOD = 1000000007n;
  const n = conversions.length + 1;
  // Links go both ways: forward multiplies by the factor, backward divides by it.
  const links = Array.from({ length: n }, () => []);
  for (const [source, target, factor] of conversions) {
    links[source].push([target, BigInt(factor), 1n]);
    links[target].push([source, 1n, BigInt(factor)]);
  }
  // Inverse modulo MOD by the extended Euclidean algorithm.
  const inverse = value => {
    let [a, b, x, y] = [value % MOD, MOD, 1n, 0n];
    while (b !== 0n) { const k = a / b; [a, b] = [b, a - k * b]; [x, y] = [y, x - k * y]; }
    return ((x % MOD) + MOD) % MOD;
  };
  // Walk the tree from unitA, carrying the exact fraction top / bottom of units of the current kind per unit of unitA.
  return queries.map(([unitA, unitB]) => {
    const stack = [[unitA, -1, 1n, 1n]];
    while (stack.length) {
      const [unit, from, top, bottom] = stack.pop();
      if (unit === unitB) return Number((top % MOD) * inverse(bottom) % MOD);
      for (const [next, times, per] of links[unit]) if (next !== from) stack.push([next, unit, top * times, bottom * per]);
    }
    return -1;
  });
}

