function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 2 + pick(8);
  const shape = ['random', 'random', 'chain', 'star', 'deep'][pick(5)];
  // Unit 0 stays the root; the other labels are shuffled so children are not always numbered after their parents.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 1; i--) { const j = 1 + pick(i); [order[i], order[j]] = [order[j], order[i]]; }
  const bigFactors = rand() < 0.6;
  const conversions = [];
  for (let i = 1; i < n; i++) {
    const parent = shape === 'chain' ? i - 1 : shape === 'star' ? 0 : shape === 'deep' ? Math.max(0, i - 1 - pick(3)) : pick(i);
    conversions.push([order[parent], order[i], bigFactors ? 1 + pick(1000000000) : 1 + pick(6)]);
  }
  // List the conversions in random order, so a child may come before its parent.
  for (let i = conversions.length - 1; i > 0; i--) { const j = pick(i + 1); [conversions[i], conversions[j]] = [conversions[j], conversions[i]]; }
  const q = size === 'large' ? 1500 + pick(501) : 1 + pick(8);
  const queries = Array.from({ length: q }, () => [pick(n), pick(n)]);
  return [conversions, queries];
}
